from html import escape
CHAPTER='/assets/downloads/Earning_Power_Exit_Power_First_Chapter.pdf'
WORKSHEETS='/assets/downloads/Earning_Power_Exit_Power_Worksheets.pdf'
def resource_form(name,button,download=None):
    action='/book/first-chapter/received' if name=='sn-free-chapter' else '/worksheets/received' if name=='sn-worksheets' else '/cohort-interest-received'
    purpose='an email copy of the printable' if download else 'a reply about the January cohort' if name=='sn-january-enquiry' else 'future cohort dates'
    hidden=f'<input type="hidden" name="form-name" value="{name}"><input type="hidden" name="sn-form" value="{name}"><input type="hidden" name="consent-version" value="sn-2026-10-29"><input type="hidden" name="consent" value="yes">'
    return f'''<form name="{name}" method="POST" action="{action}" data-netlify="true" netlify-honeypot="bot-field" data-capture data-success="Your request has been received." data-redirect="{action}">{hidden}<p hidden><label>Leave this empty <input name="bot-field" tabindex="-1" autocomplete="off"></label></p><label class="field">First name<input name="name" required maxlength="100" autocomplete="given-name"></label><label class="field">Email address<input name="email" type="email" required maxlength="254" autocomplete="email"></label><label class="consent"><input type="checkbox" name="newsletter-consent" value="yes">Also send me The Optional Career, weekly, plus occasional course and cohort invitations.</label><p class="fine">By submitting, you request {purpose}. Newsletter signup is optional. Unsubscribe at any time. <a href="/privacy">Privacy details</a>.</p><button class="btn" type="submit">{button}</button><p class="form-status" role="status" aria-live="polite"></p></form>'''
def resource_page(kind):
    chapter=kind=='chapter'
    heading='Read the Prologue and Chapter One free.' if chapter else 'The four worksheets from the book. Free.'
    desc='From Earning Power × Exit Power = Optionality. A printable PDF to read at your own pace.' if chapter else 'Four printable exercises for examining your career, commitments and room to move.'
    cards='' if chapter else '<div class="grid-2">'+''.join(f'<article class="card"><h3>{a}</h3><p>{b}</p></article>' for a,b in [('The Runway','How many months your usable reserve covers.'),('The Ladder Audit','Examine how much of your visible output is doing or deciding.'),('The Concentration Map','See how several parts of your life can depend on one employer.'),('The Number','Explore four different meanings of Enough.')])+'</div>'
    file=CHAPTER if chapter else WORKSHEETS
    name='sn-free-chapter' if chapter else 'sn-worksheets'
    form=resource_form(name,'Get my free PDF',file).replace(' data-capture ',f' data-resource-form="{kind}" ').replace(f' data-redirect="'+('/book/first-chapter/received' if chapter else '/worksheets/received')+'"','')
    return f'<section class="wrap page-hero"><span class="eyebrow">Free printable / The book</span><h1>{heading}</h1><p class="lede">{desc}</p></section><section class="wrap section resource-layout">{cards}<div class="grid-2"><div><h2>Take it off the screen.</h2><p>Share your name and email to unlock the printable PDF. Download, print and write on the pages.</p><p>Your download unlocks after your details are saved. We’ll also email your copy. Newsletter signup is optional.</p></div><div class="form-box" data-resource-card><div data-resource-content><h2>Get your copy.</h2>{form}</div><div data-resource-success hidden tabindex="-1"><h2>Your PDF is ready.</h2><a class="btn" data-resource-download download>Download the printable PDF</a><p>Your request is saved. Keep your copy now.</p></div></div></div></section><script type="module" src="/assets/lib/resource-capture.js?v=1"></script>'
def received(kind):
    chapter=kind=='chapter'
    file=CHAPTER if chapter else WORKSHEETS
    url='/book' if chapter else '/runway'
    label='See the book' if chapter else 'Find your runway'
    return '<section class="wrap page-hero"><span class="eyebrow">Your printable</span><h1>Get your printable copy.</h1><p class="lede">Enter your name and email on the resource page to unlock your PDF.</p><a class="btn" href="'+('/philosophy#preorder' if chapter else '/worksheets/book')+'">Get the free PDF</a></section>'

def calculator():
    return '''<section class="wrap section" id="runway-calculator"><div class="section-heading"><div><span class="eyebrow">Your household, in months</span><h2>Find your runway.</h2></div><p>Usable reserves divided by the monthly shortfall if your salary stopped. Try a second scenario with lower continuing income or higher costs.</p></div><div class="grid-2" data-runway><form data-runway-form><label class="field">Money available for this decision (₹)<input name="reserve" type="number" min="0" step="any" inputmode="decimal" required aria-describedby="reserve-note"></label><p class="fine" id="reserve-note">After likely tax and selling costs. Exclude your home, locked retirement funds, unvested shares and money reserved for other goals, including any emergency reserve you will not use.</p><label class="field">Monthly household costs (₹)<input name="costs" type="number" min="0.01" step="any" inputmode="decimal" required></label><label class="field">Reliable continuing take-home income (₹/month, optional)<input name="income" type="number" min="0" step="any" inputmode="decimal" placeholder="0"></label><button class="btn secondary" type="submit">Calculate runway</button><p class="fine">Include annual bills divided by twelve and any extra care or work costs. Nothing you enter in this calculator is stored or sent.</p></form><div class="card soft" aria-live="polite" aria-atomic="true"><h3 data-runway-number>Your runway</h3><p data-runway-reading>Enter reserves, monthly costs and any reliable continuing income.</p><p class="fine" data-runway-band></p><p class="fine">A simplified calculation with fixed costs and income, no investment return and no unexpected expenses. Inflation, tax and changes in income affect the result. This is not an investment or retirement plan.</p><a class="btn" href="/worksheets">Get the free worksheets</a></div></div><noscript><p>Divide usable reserves by monthly costs minus reliable continuing income. If income covers costs, there is no current drawdown under those assumptions.</p></noscript></section>'''
def check_page():
    return '''<section class="wrap page-hero"><span class="eyebrow">The Starting Point Check</span><h1>Where do you stand?<br>A 6-minute check.</h1><p class="lede">Twelve questions about how your work reads at the next level, and how much room you have to move. Financial questions use ranges, never exact amounts.</p><p>This is a self-reflection exercise, not a validated assessment, salary score or promotion prediction. Choose the situation you want to explore; the two paths are not comparable scores.</p></section><section class="wrap narrow section" style="padding-top:0"><div id="starting-check"><button class="btn" id="starting-begin" type="button">Start the free check</button><p class="fine">Answers stay in this tab until you choose to submit an email report request. Enter your name and email at the end to see and save your result. Joining the newsletter is optional.</p></div><section id="starting-result" hidden></section><section id="starting-email" hidden><h2>Where should we send your report?</h2><p>Enter your name and email to unlock your result. Joining the newsletter is optional.</p><form name="sn-starting-point" data-starting-form method="POST" action="/request-received" data-netlify="true" netlify-honeypot="bot-field"><input type="hidden" name="form-name" value="sn-starting-point"><input type="hidden" name="sn-form" value="sn-starting-point"><input type="hidden" name="consent-version" value="sn-2026-10-29"><input type="hidden" name="test-version"><input type="hidden" name="answers"><p hidden><label>Leave empty <input name="bot-field" tabindex="-1" autocomplete="off"></label></p><label class="field">First name<input name="name" required maxlength="100" autocomplete="given-name"></label><label class="field">Email address<input name="email" type="email" required maxlength="254" autocomplete="email"></label><input type="hidden" name="consent" value="yes"><label class="consent"><input type="checkbox" name="newsletter-consent" value="yes">Also send me The Optional Career, weekly, and occasional course and cohort invitations.</label><p class="fine">Submitting shares your answers, including the financial ranges and current decision, with Netlify and MailerLite to provide your report. Newsletter signup is optional. <a href="/privacy">Privacy details</a>.</p><button class="btn secondary" type="submit">Show my result</button><p class="form-status" role="status" aria-live="polite"></p></form></section><noscript><p>The interactive check needs JavaScript. You can <a href="/worksheets">use the printable worksheets</a> or <a href="/conversation">book a free call</a>.</p></noscript></section><section class="wrap section"><h2>Want to practice a specific skill?</h2><p>The <a href="/tests/senior-level-judgment">Senior-Level Judgment practice check</a> and <a href="/tests/leadership-visibility">Leadership Visibility practice check</a> use fictional workplace situations.</p></section>'''
def cohort():
    cta='<a class="btn" href="https://rzp.io/rzp/Jan27TSUTSL">Join the January cohort</a>'
    call='<a class="text-link" href="/conversation">Not sure it fits? Book a free 20-minute call</a>'
    weeks=[('9 January','Outcome Translation · Speak Business','Turn your updates into what changed for the business.','Practice explaining a project’s effect in a sentence a VP can repeat.'),('16 January','Recommend Under Ambiguity · Deliberate Elimination','Make the call before all the facts are in.','Recommend a course of action and say what moves out to make room.'),('23 January','Legibility · Reduce Your Boss’s Uncertainty','Make your work easier for your boss to back.','Make the result, risk and decision visible, with fewer surprises.'),('30 January','Lateral Influence · Disagree Without Damage','Work across teams without a status fight.','Understand competing priorities and disagree with evidence and an alternative.'),('6 February','Delegate to People · Delegate to AI','Hand over real ownership.','Define boundaries and checks that fit the risk, for people and AI-assisted work.'),('13 February','Connect the Dots · The Readiness Conversation','Ask for the next role with evidence.','Link your work to the bigger picture and leave with your one-page Readiness Note.')]
    cards=''.join(f'<article class="card"><span class="eyebrow">Week {i+1} / {d} 2027</span><h3>{h}</h3><p>{b}</p><p class="fine">{s}</p></article>' for i,(d,s,h,b) in enumerate(weeks))
    email='''Subject: Request: leadership program in January

Hi [manager’s name],

I’d like to join The Step Up to Senior Leadership, a six-week live program starting 9 January 2027.

It works on business communication, decisions with incomplete information, influence across teams, and delegating ownership. Each week I practice on an anonymized example from my own work, with feedback.

Time: six Saturdays at 11 AM IST, 90 minutes, on Google Meet. About three hours a week including preparation.
Program fee: ₹17,999, including 18% GST. Please contact the provider about a company invoice before payment.
Details: https://sayantannandi.com/step-up/cohort

Could we use the learning budget for this? I’m happy to share what I’m working on after each week.

[Your name]'''
    return f'''<section class="wrap hero"><div class="hero-grid"><div><span class="eyebrow">January 2027 / Live cohort</span><h1>Practice the work<br>of your next role.</h1><p class="lede">Six weeks for managers in GCCs, IT services and global companies who are preparing for broader responsibility, or have been passed over and want clearer evidence of readiness.</p><p>Starts Saturday 9 January 2027 · Six Saturdays at 11 AM IST · 90 minutes on Google Meet · Up to 20 participants</p><div class="actions">{cta}</div>{call}<p class="fine">Registration is open. Payment is processed securely by Razorpay.</p></div><img class="portrait" src="/assets/images/sayantan-portrait.webp" width="600" height="600" alt="Sayantan Nandi, cohort instructor"></div></section>
<section class="wrap section"><h2>You were trusted to deliver.<br>The next role asks for more.</h2><ul class="details-list"><li>You send a clean status update. Your VP replies, “What do you need from me?”</li><li>You’ve heard “be more strategic” in two reviews, without an example of what to change.</li><li>A new priority lands. You say yes, then work late to fit it in.</li><li>Two teams disagree, and the decision lands on your boss’s desk again.</li></ul><p style="margin-top:24px">These situations ask for judgment, influence and ownership that strong delivery alone may not demonstrate.</p></section>
<section class="wrap narrow section"><h2>Why practice needs a place in your week.</h2><p>A leadership workshop can make sense in the room while leaving Monday’s habits untouched.</p><p>In this cohort you bring an anonymized update, decision or disagreement, work through it, and use feedback to revise your attempt.</p><p>Every Saturday gives you a reason to prepare something concrete. The following week gives you a chance to try again.</p><div class="actions">{cta}</div></section>
<section class="wrap section" id="schedule"><h2>Six Saturdays.<br>Six kinds of work to practice.</h2><div class="grid-2">{cards}</div><p style="margin-top:26px">Each week: two short lessons, 90 minutes live, and one focused piece of your work for written feedback. Plan for about three hours in total.</p><p class="fine">Sessions run 11 AM to 12:30 PM IST. That is 9:30 to 11 AM in Dubai and 1:30 to 3 PM in Singapore.</p></section>
<section class="wrap section"><div class="grid-2"><div><span class="eyebrow">Your instructor</span><h2>Sayantan Nandi</h2><p>I spent fifteen years in technology, most recently as IT Director at Schneider Electric, leading teams of more than 200 people.</p><p>I’m an ISB MBA and the author of Earning Power × Exit Power = Optionality. My teaching draws on the decisions, reviews and organizational constraints I worked with in leadership.</p><p>The aim is to make the work behind broader responsibility easier to recognize and practice.</p></div><div class="card"><h3>Is this for you?</h3><p>You lead a team or substantial work, typically with ten or more years of experience. You want senior or global scope, or a recent promotion cycle passed you by.</p><p>You can bring a real example and make time for the exercises.</p><p>This is not CV or interview coaching. It cannot create a role, secure a sponsor or guarantee a promotion.</p></div></div><div class="actions">{cta}</div></section>
<section class="wrap section"><h2>See the work before you pay.</h2><p class="fine">A fictional Week 1 exercise. Scenario: 11 of 15 services supporting finance have migrated. Finance has verified that its close is one day faster. The remaining four migrations need a vendor-contract decision by Friday.</p><div class="grid-2"><article class="card"><span class="eyebrow">Activity update</span><p>“This sprint the team migrated 11 services and closed 42 tickets.”</p></article><article class="card soft"><span class="eyebrow">Outcome and decision</span><p>“Finance now closes the month a day earlier, following the 11 service migrations completed this sprint. The remaining four need your decision on the vendor contract by Friday.”</p></article></div><div class="actions"><a class="btn secondary" href="/step-up/sample">Read a free lesson</a>{call}</div></section>
<section class="wrap section" id="price"><div class="grid-2"><div><h2>Everything you get.</h2><ul class="details-list"><li>Six live sessions with Sayantan, 90 minutes each</li><li>Twelve lessons: videos, study guides and practice books</li><li>Written feedback on one focused submission each week</li><li>Your one-page Readiness Note</li><li>A group of up to 20 peers</li><li>Session recordings for 90 days after the final session</li><li>Promotion Case Builder, Review Room Kit and The Executive Hour</li></ul></div><div class="form-box"><span class="eyebrow">One payment</span><h2 class="cohort-price">₹17,999</h2><p>One payment, including 18% GST. Review the payment details on Razorpay before paying.</p><p>Registration closes Wednesday 6 January 2027 at 11:59 PM IST, or when 20 paid places are filled.</p><div class="actions">{cta}</div>{call}<p class="fine">The independent course covers the same twelve lessons. The cohort adds live sessions, peer discussion and feedback. Existing buyers: <a href="/help">ask about your access before paying again</a>.</p></div></div></section>
<section class="wrap narrow section"><h2>Ask your company to pay.</h2><p>If your company has a learning budget, adapt this request. Ask about an invoice in the company’s name before paying.</p><pre class="email-template" id="company-email">{escape(email)}</pre><button class="btn secondary" type="button" id="copy-company-email">Copy the email</button><p class="fine" id="copy-email-status" role="status"></p><p>Invoice questions: <a href="mailto:hello@sayantannandi.com">hello@sayantannandi.com</a>.</p></section>
<section class="wrap section"><div class="callout"><h2>Try the first session.<br>If it does not fit, get a full refund.</h2><p>Email hello@sayantannandi.com from your purchase address by Saturday 16 January 2027, before 11 AM IST (the start of session 2). This includes cancellations before the start and requests after attending session 1 or watching its recording.</p><p>No reason is required. A full refund goes to the original payment method. <a href="/refunds">Read the refund terms</a>.</p><p class="fine">No promotion, pay increase or job offer is guaranteed. The commitment is to the stated practice, materials and feedback.</p></div></section>
<section class="wrap narrow section"><h2>A few practical details.</h2><div class="faq"><details><summary>What if I miss a Saturday?</summary><p>Use the recording and send that week’s focused submission. The cohort includes one written feedback response per weekly submission, rather than unlimited editing or private coaching.</p></details><details><summary>How do recordings and confidentiality work?</summary><p>Sessions are recorded for registered cohort members. Use anonymized or fictional examples and leave out employer, customer and personal data. Participants must not share recordings or anyone else’s work outside the group. An absolute guarantee about another participant’s behavior is not possible.</p></details><details><summary>How long can I access the materials?</summary><p>Course materials remain available for as long as the course is hosted, under the published course terms. Cohort recordings are available for 90 days after the final session. Submit one focused piece by Tuesday at 11:59 PM IST each week; written feedback follows within three working days. Late submissions receive feedback when capacity allows. These arrangements also apply to the final week.</p></details><details><summary>What happens after registration?</summary><p>Keep your Razorpay receipt. Complete the cohort intake after payment. Within two working days of your intake and payment verification, I will email the Google Meet joining details and course and workbook access instructions. You can download the session calendar from the customer page. If you need help, email hello@sayantannandi.com with your purchase address and order reference. This public page cannot verify a payment.</p></details><details><summary>Do I need to work in technology?</summary><p>Examples lean on technology, data and operations. The practice is relevant wherever you make decisions and influence work across teams.</p></details></div></section>
<section class="wrap section" id="enrolment"><div class="grid-2"><div><span class="eyebrow">9 January to 13 February 2027</span><h2>Join the January cohort.</h2><p>Registration closes 6 January 2027 at 11:59 PM IST, or when the 20 places are filled. Review the fee and terms, then continue to Razorpay to pay.</p><p>The fee is ₹17,999. Keep your payment confirmation and use the customer access page for next steps.</p>{call}</div><div class="form-box"><h3>Make time for the work.</h3><p>Six Saturdays, twelve lessons, and feedback on your own attempts.</p>{cta}<p class="fine"><a href="/step-up/cohort-thank-you">After payment: intake and access</a></p></div></div></section><section class="wrap narrow section" id="next-cohort"><h2>Prefer a later group?</h2><p>Ask to hear when future cohort dates are available.</p><details><summary>Join the next-cohort list</summary>{resource_form('sn-next-cohort','Tell me about the next cohort')}</details></section><div class="cohort-sticky">{cta}<a href="/conversation">Book a free call</a></div>'''
